import { logError } from "@/lib/logger";

type GradeRow = {
  session_id: string;
  q_idx: number;
  [key: string]: unknown;
};

function isOnConflictConstraintError(error: unknown): boolean {
  const e = error as { code?: string; message?: string } | null;
  const message = e?.message || "";
  return (
    e?.code === "42P10" ||
    /no unique or exclusion constraint matching the ON CONFLICT specification/i.test(
      message
    )
  );
}

/**
 * Upsert grades by (session_id, q_idx).
 * Falls back to update-then-insert when DB is missing the unique constraint.
 */
export async function upsertGradesBySessionQuestion(
  supabase: {
    from: (table: string) => {
      upsert: (
        values: GradeRow[],
        options: { onConflict: string }
      ) => {
        select: (
          columns: string
        ) => Promise<{ data: Array<{ q_idx: number }> | null; error: unknown }>;
      };
      update: (value: GradeRow) => {
        eq: (column: string, value: string | number) => {
          eq: (column: string, value: string | number) => {
            select: (
              columns: string
            ) => Promise<{ data: Array<{ q_idx: number }> | null; error: unknown }>;
          };
        };
      };
      insert: (value: GradeRow) => {
        select: (
          columns: string
        ) => {
          single: () => Promise<{ data: { q_idx: number } | null; error: unknown }>;
        };
      };
    };
  },
  rows: GradeRow[],
  source: string
): Promise<number[]> {
  if (rows.length === 0) return [];

  const { data: upsertRows, error: upsertError } = await supabase
    .from("grades")
    .upsert(rows, { onConflict: "session_id,q_idx" })
    .select("q_idx");

  if (!upsertError) {
    return (upsertRows || []).map((row) => row.q_idx);
  }

  if (!isOnConflictConstraintError(upsertError)) {
    throw upsertError;
  }

  logError("[GRADES_UPSERT] Missing onConflict constraint, using fallback path", upsertError, {
    path: "lib/grades-upsert.ts",
    additionalData: { source, rows: rows.length },
  });

  const qIdxs: number[] = [];
  for (const row of rows) {
    const { data: updatedRows, error: updateError } = await supabase
      .from("grades")
      .update(row)
      .eq("session_id", row.session_id)
      .eq("q_idx", row.q_idx)
      .select("q_idx");

    if (updateError) throw updateError;

    if (updatedRows && updatedRows.length > 0) {
      qIdxs.push(row.q_idx);
      continue;
    }

    const { data: insertedRow, error: insertError } = await supabase
      .from("grades")
      .insert(row)
      .select("q_idx")
      .single();

    if (insertError) throw insertError;
    if (insertedRow) qIdxs.push(insertedRow.q_idx);
  }

  return qIdxs;
}

import crypto from "crypto";
import OpenAI from "openai";
import { getSupabaseServer } from "@/lib/supabase-server";
import { logError } from "@/lib/logger";
import {
  AI_PRICING_VERSION,
  type AiEndpoint,
  type AiFeature,
  type AiUsageSnapshot,
  calculateEstimatedCostUsdMicros,
  resolveModelPricing,
} from "@/lib/ai-pricing";
import {
  OpenAITimeoutError,
  callOpenAIWithTelemetry,
} from "@/lib/openai";

type JsonRecord = Record<string, unknown>;

interface TrackedRequestContext {
  feature: AiFeature;
  route: string;
  endpoint: AiEndpoint;
  model: string;
  userId?: string | null;
  examId?: string | null;
  sessionId?: string | null;
  qIdx?: number | null;
  metadata?: JsonRecord;
}

interface TrackedRequestOptions<T> {
  timeoutMs?: number;
  maxAttempts?: number;
  metadataBuilder?: (result: T) => JsonRecord | undefined;
}

interface OpenAIRequestFailure {
  error: unknown;
  attemptCount: number;
  latencyMs: number;
}

export interface TrackedOpenAIResult<T> {
  data: T;
  usage: AiUsageSnapshot | null;
  requestId: string | null;
  responseId: string | null;
  attemptCount: number;
  latencyMs: number;
  estimatedCostUsdMicros: number;
}

type AiEventInsert = {
  provider: string;
  endpoint: AiEndpoint;
  feature: AiFeature;
  route: string;
  model: string;
  user_id?: string | null;
  exam_id?: string | null;
  session_id?: string | null;
  q_idx?: number | null;
  status: "success" | "error" | "timeout";
  attempt_count: number;
  latency_ms: number | null;
  input_tokens: number | null;
  output_tokens: number | null;
  cached_input_tokens: number | null;
  reasoning_tokens: number | null;
  total_tokens: number | null;
  estimated_cost_usd_micros: number;
  pricing_version: string;
  request_id: string | null;
  response_id: string | null;
  error_code: string | null;
  metadata: JsonRecord;
};

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === "object" && value !== null;
}

function safeMetadata(metadata?: JsonRecord): JsonRecord {
  return metadata ? { ...metadata } : {};
}

function extractRequestId(result: unknown): string | null {
  if (!isRecord(result)) return null;

  const requestId = result._request_id;
  return typeof requestId === "string" ? requestId : null;
}

function extractResponseId(result: unknown): string | null {
  if (!isRecord(result)) return null;

  const id = result.id;
  return typeof id === "string" ? id : null;
}

export function extractUsageFromOpenAIResult(
  endpoint: AiEndpoint,
  result: unknown
): AiUsageSnapshot | null {
  if (!isRecord(result)) return null;

  if (endpoint === "responses") {
    const usage = isRecord(result.usage) ? result.usage : null;
    if (!usage) return null;

    const inputDetails = isRecord(usage.input_tokens_details)
      ? usage.input_tokens_details
      : null;
    const outputDetails = isRecord(usage.output_tokens_details)
      ? usage.output_tokens_details
      : null;

    return {
      inputTokens:
        typeof usage.input_tokens === "number" ? usage.input_tokens : null,
      outputTokens:
        typeof usage.output_tokens === "number" ? usage.output_tokens : null,
      cachedInputTokens:
        inputDetails && typeof inputDetails.cached_tokens === "number"
          ? inputDetails.cached_tokens
          : 0,
      reasoningTokens:
        outputDetails && typeof outputDetails.reasoning_tokens === "number"
          ? outputDetails.reasoning_tokens
          : 0,
      totalTokens:
        typeof usage.total_tokens === "number" ? usage.total_tokens : null,
    };
  }

  if (endpoint === "embeddings") {
    const usage = isRecord(result.usage) ? result.usage : null;
    if (!usage) return null;

    return {
      inputTokens:
        typeof usage.prompt_tokens === "number" ? usage.prompt_tokens : null,
      outputTokens: 0,
      cachedInputTokens: 0,
      reasoningTokens: 0,
      totalTokens:
        typeof usage.total_tokens === "number" ? usage.total_tokens : null,
    };
  }

  const usage = isRecord(result.usage) ? result.usage : null;
  if (!usage) return null;

  const promptDetails = isRecord(usage.prompt_tokens_details)
    ? usage.prompt_tokens_details
    : null;
  const completionDetails = isRecord(usage.completion_tokens_details)
    ? usage.completion_tokens_details
    : null;

  return {
    inputTokens:
      typeof usage.prompt_tokens === "number" ? usage.prompt_tokens : null,
    outputTokens:
      typeof usage.completion_tokens === "number" ? usage.completion_tokens : null,
    cachedInputTokens:
      promptDetails && typeof promptDetails.cached_tokens === "number"
        ? promptDetails.cached_tokens
        : 0,
    reasoningTokens:
      completionDetails && typeof completionDetails.reasoning_tokens === "number"
        ? completionDetails.reasoning_tokens
        : 0,
    totalTokens:
      typeof usage.total_tokens === "number" ? usage.total_tokens : null,
  };
}

export function buildAiTextMetadata(params: {
  inputText?: string | string[];
  outputText?: string | null;
  extra?: JsonRecord;
}): JsonRecord {
  const metadata: JsonRecord = { ...(params.extra ?? {}) };
  const input = Array.isArray(params.inputText)
    ? params.inputText.join("\n\n")
    : params.inputText;

  if (typeof input === "string" && input.length > 0) {
    metadata.input_chars = input.length;
    metadata.prompt_hash = crypto
      .createHash("sha256")
      .update(input)
      .digest("hex");
  }

  if (typeof params.outputText === "string" && params.outputText.length > 0) {
    metadata.output_chars = params.outputText.length;
  }

  return metadata;
}

function getOpenAIErrorCode(error: unknown): string | null {
  if (error instanceof OpenAITimeoutError) {
    return "timeout";
  }
  if (error instanceof OpenAI.APIError) {
    return error.code ? String(error.code) : `http_${error.status}`;
  }
  if (error instanceof Error && error.name) {
    return error.name;
  }
  return null;
}

async function insertAiEvent(event: AiEventInsert): Promise<void> {
  const supabase = getSupabaseServer();
  const { error } = await supabase.from("ai_events").insert(event);

  if (error) {
    throw error;
  }
}

function buildFailure(error: unknown): OpenAIRequestFailure {
  if (
    isRecord(error) &&
    "error" in error &&
    "attemptCount" in error &&
    "latencyMs" in error
  ) {
    const attemptCount =
      typeof error.attemptCount === "number" ? error.attemptCount : 1;
    const latencyMs = typeof error.latencyMs === "number" ? error.latencyMs : 0;

    return {
      error: error.error,
      attemptCount,
      latencyMs,
    };
  }

  return {
    error,
    attemptCount: 1,
    latencyMs: 0,
  };
}

async function persistAiEvent(event: AiEventInsert, route: string): Promise<void> {
  try {
    await insertAiEvent(event);
  } catch (trackingError) {
    await logError("Failed to insert ai_events row", trackingError, {
      path: route,
      additionalData: {
        feature: event.feature,
        endpoint: event.endpoint,
        model: event.model,
      },
    });
  }
}

export async function callTrackedOpenAI<T>(
  fn: () => Promise<T>,
  context: TrackedRequestContext,
  options?: TrackedRequestOptions<T>
): Promise<TrackedOpenAIResult<T>> {
  try {
    const { data, attemptCount, latencyMs } = await callOpenAIWithTelemetry(
      fn,
      { timeoutMs: options?.timeoutMs, maxAttempts: options?.maxAttempts }
    );
    const usage = extractUsageFromOpenAIResult(context.endpoint, data);
    const requestId = extractRequestId(data);
    const responseId = extractResponseId(data);
    const estimatedCostUsdMicros = calculateEstimatedCostUsdMicros(
      context.model,
      usage
    );
    const metadata = {
      ...safeMetadata(context.metadata),
      ...(options?.metadataBuilder?.(data) ?? {}),
    };

    if (!usage) {
      metadata.usage_missing = true;
    }
    if (!resolveModelPricing(context.model)) {
      metadata.pricing_missing = true;
    }

    await persistAiEvent(
      {
        provider: "openai",
        endpoint: context.endpoint,
        feature: context.feature,
        route: context.route,
        model: context.model,
        user_id: context.userId ?? null,
        exam_id: context.examId ?? null,
        session_id: context.sessionId ?? null,
        q_idx: context.qIdx ?? null,
        status: "success",
        attempt_count: attemptCount,
        latency_ms: latencyMs,
        input_tokens: usage?.inputTokens ?? null,
        output_tokens: usage?.outputTokens ?? null,
        cached_input_tokens: usage?.cachedInputTokens ?? null,
        reasoning_tokens: usage?.reasoningTokens ?? null,
        total_tokens: usage?.totalTokens ?? null,
        estimated_cost_usd_micros: usage ? estimatedCostUsdMicros : 0,
        pricing_version: AI_PRICING_VERSION,
        request_id: requestId,
        response_id: responseId,
        error_code: null,
        metadata,
      },
      context.route
    );

    return {
      data,
      usage,
      requestId,
      responseId,
      attemptCount,
      latencyMs,
      estimatedCostUsdMicros: usage ? estimatedCostUsdMicros : 0,
    };
  } catch (error) {
    const failure = buildFailure(error);
    const status =
      failure.error instanceof OpenAITimeoutError ? "timeout" : "error";

    await persistAiEvent(
      {
        provider: "openai",
        endpoint: context.endpoint,
        feature: context.feature,
        route: context.route,
        model: context.model,
        user_id: context.userId ?? null,
        exam_id: context.examId ?? null,
        session_id: context.sessionId ?? null,
        q_idx: context.qIdx ?? null,
        status,
        attempt_count: failure.attemptCount,
        latency_ms: failure.latencyMs,
        input_tokens: null,
        output_tokens: null,
        cached_input_tokens: null,
        reasoning_tokens: null,
        total_tokens: null,
        estimated_cost_usd_micros: 0,
        pricing_version: AI_PRICING_VERSION,
        request_id: null,
        response_id: null,
        error_code: getOpenAIErrorCode(failure.error),
        metadata: safeMetadata(context.metadata),
      },
      context.route
    );

    throw failure.error;
  }
}

